import type { Course, Lesson } from './data-provider';

export type DemonstrationTrace = { line: number; state: string; output: string; explanation: string };
export type LessonExperiment = { id: string; label: string; input: string; result: string; reason: string; lines?: string[]; trace?: DemonstrationTrace[] };
export type LessonDemonstration = {
  id: string;
  goal: string;
  concept: string;
  why: string;
  steps: Array<{ title: string; action: string; reason: string; visibleResult: string }>;
  misconception: { belief: string; correction: string };
  prediction: { question: string; options: string[]; answer: string; explanation: string };
  prompt: { starter: string; improved: string; sampleOutput: string; whyBetter: string };
  transfer: string;
  /** Trace line numbers are zero-based indices into lines. Examples are authored illustrations, not executed user code. */
  code: { language: string; lines: string[]; trace: DemonstrationTrace[] } | null;
  experiments: LessonExperiment[];
};


type Step = [title: string, action: string, reason: string, visibleResult: string];
type Case = [label: string, input: string, result: string, reason: string];
type Seed = Omit<LessonDemonstration, 'id'>;
function make(
  goal: string, concept: string, why: string, steps: Step[],
  misconception: [belief: string, correction: string],
  prediction: [question: string, options: string[], answer: string, explanation: string],
  prompt: [starter: string, improved: string, sampleOutput: string, whyBetter: string],
  transfer: string, cases: Case[], code: LessonDemonstration['code'] = null,
): Seed {
  return { goal, concept, why, steps: steps.map(([title, action, reason, visibleResult]) => ({ title, action, reason, visibleResult })),
    misconception: { belief: misconception[0], correction: misconception[1] },
    prediction: { question: prediction[0], options: prediction[1], answer: prediction[2], explanation: prediction[3] },
    prompt: { starter: prompt[0], improved: prompt[1], sampleOutput: prompt[2], whyBetter: prompt[3] }, transfer, code,
    experiments: cases.map(([label, input, result, reason], index) => ({ id: `case-${index + 1}`, label, input, result, reason })) };
}

function program(language: string, lines: string[], trace: Array<[line: number, state: string, output: string, explanation: string]>): NonNullable<LessonDemonstration['code']> {
  return { language, lines, trace: trace.map(([line, state, output, explanation]) => ({ line, state, output, explanation })) };
}

