// These are explicit, bounded worked comparisons. They never execute learner-supplied code.
function attachCodeCases(key: string, examples: Array<NonNullable<LessonDemonstration['code']>>) {
  const seed = authored[key];
  if (!seed || examples.length !== seed.experiments.length) throw new Error(`Invalid code comparison: ${key}`);
  examples.forEach((example, index) => {
    seed.experiments[index] = { ...seed.experiments[index], lines: example.lines, trace: example.trace };
  });
}

