export const authoredLessonDemonstrationIds = (): string[] => Object.keys(authored);

export function getLessonDemonstration(course: Course, lesson: Lesson): LessonDemonstration {
  const key = `${course.id}:${lesson.id}`;
  const seed = authored[key];
  if (!seed) throw new Error(`Missing authored learning demonstration: ${key}`);
  return { id: `demonstration:${key}`, ...seed };
}
